{"implementation":"def solve(case):
    nodes = list(case.get("nodes", []))
    core = case.get("core_distance", {})
    order = {node: index for index, node in enumerate(nodes)}

    edges = []
    for index, entry in enumerate(case.get("distances", [])):
        if len(entry) != 3:
            continue
        left, right, distance = entry
        if left not in order or right not in order or left == right:
            continue
        weight = max(core[left], core[right], distance)
        a, b = (left, right) if order[left] <= order[right] else (right, left)
        edges.append((weight, order[a], order[b], index, a, b))

    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}

    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node

    def union(left, right):
        left_root = find(left)
        right_root = find(right)
        if left_root == right_root:
            return False
        if rank[left_root] < rank[right_root]:
            left_root, right_root = right_root, left_root
        parent[right_root] = left_root
        if rank[left_root] == rank[right_root]:
            rank[left_root] += 1
        return True

    mst_edges = []
    for weight, _, _, _, left, right in sorted(edges):
        if union(left, right):
            mst_edges.append([left, right, weight])

    return {"mst_edges": mst_edges}
